/// Returns `false` if the node is disabled by a `#[cfg]` attribute in the given crate.
pub fn is_cfg_enabled(&self, krate: Crate, owner: &dyn ast::HasAttrs) -> bool {
    let cfg_options = krate.id.cfg_options(self.db);
    hir_expand::attrs::expand_cfg_attr(
        ast::attrs_including_inner(owner),
        || cfg_options,
        |attr, _| {
            if let ast::Meta::CfgMeta(attr) = attr
                && let Some(cfg_predicate) = attr.cfg_predicate()
                && let cfg = cfg::CfgExpr::parse_from_ast(cfg_predicate)
                && cfg_options.check(&cfg) == Some(false)
            {
                ControlFlow::Break(())
            } else {
                ControlFlow::Continue(())
            }
        },
    )
    .is_none()
}

pub fn lint_attrs(
    &self,

    ast::Expr::BlockExpr(b) => {
        let krate = sema.scope(b.syntax()).map(|scope| scope.krate());
        let enabled = |e: &ast::Expr| krate.is_none_or(|krate| sema.is_cfg_enabled(krate, e));
        match b.tail_expr() {
            Some(tail) if enabled(&tail) => Some(tail),
            Some(_) => b
                .statements()
                .filter(|stmt| match stmt {
                    ast::Stmt::ExprStmt(s) => s.expr().is_none_or(|e| enabled(&e)),
                    ast::Stmt::LetStmt(s) => krate.is_none_or(|k| sema.is_cfg_enabled(k, s)),
                    _ => true,
                })
                .last()
                .and_then(|stmt| match stmt {
                    ast::Stmt::ExprStmt(s) if s.semicolon_token().is_none() => s.expr(),
                    _ => None,
                }),
            None => None,
        }
    }
    e => Some(e),
};

